    fonteNome: "CBN - Política",
    fonteUrl: "https://cbn.globo.com/coberturas/eleicoes-2026/noticia/2026/10/05/aliados-de-trump-miliei-e-presidente-da-colombia-comemoram-primeiro-lugar-de-flavio-bolsonaro-nas-eleicoes.ghtml",
    fontesAdicionais: [{"nome":"STF Notícias","url":"https://portal.stf.jus.br/noticias/"},{"nome":"MPF","url":"https://www.mpf.mp.br/pgr/noticias-pgr"}],
    entidades: [],
    aeo: [{"pergunta":"O que aconteceu?","resposta":"Diversas personalidades políticas da extrema-direita ou da direita nos Estados Unidos e na América Latina comemoram o senador Flávio Bolsonaro, do PL, ter ficado em primeiro lugar na disputa de primeiro turno das eleições de 2026 contra o candidato à reeleição Lula, do PT."},{"pergunta":"Qual é o ponto principal?","resposta":"Entre os presidentes, comentaram Javier Milei, da Argentina, e Abelardo De La Espriella, da Colômbia."},{"pergunta":"Quais são os dados mais importantes?","resposta":"O primeiro parabenizou Flávio pelo que chamou de 'eleição histórica' e defendeu que a 'liberdade avança no Brasil'."},{"pergunta":"Qual é o contexto?","resposta":"'O continente americano é de cidadãos que querem viver em liberdade. Espero que em breve possamos começar a trabalhar juntos para que a Argentina e o Brasil continuem sendo grandes parceiros comerciais, culturais e políticos. As oportunidades para as nossas nações, trabalhando juntas, são infinitas', disse."},{"pergunta":"Quais são os próximos desdobramentos?","resposta":"Já Espriella disse que o coração 'estava com o Brasil'."}],
